import{_ as r,l as s,o as a,c as d,v as t,p as l,x as i,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"exit 与回收","description":"","frontmatter":{"title":"exit 与回收","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/exit-reap.md","filePath":"cs/exit-reap.md","lastUpdated":1789023840000}'),m={name:"cs/exit-reap.md"};function h(_,e,x,B,E,f){const o=s("Mermaid");return a(),d("div",null,[e[1]||(e[1]=t('<h1 id="exit-与回收" tabindex="-1">exit 与回收 <a class="header-anchor" href="#exit-与回收" aria-label="Permalink to &quot;exit 与回收&quot;">​</a></h1><div class="epigraph"><p>退出不是只把 PC 停掉：要拆文件、内存、通知父进程，并在最后留下可供 wait 的瘦 PCB。</p><footer>—— 据 Love, Linux Kernel Development；Tanenbaum MOS 整理</footer></div><p><a href="/cs/orphan-init">上一课</a>保证父指针在父先走时仍指向会 wait 的人。<a href="/cs/wait-zombie">wait 与僵尸</a>说明结束态要留退出码。缺口是把 <strong>exit 路径</strong>按顺序列出来：哪些资源在进入僵尸前释放，哪些必须留到 wait 之后。本课钉回收顺序，不把每个子系统的析构函数写成清单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户调用 <code>_exit</code> 或最后一条线程结束，内核必须：停止其他线程（进程退出）、把地址空间引用减掉、关闭文件描述符、去掉信号处理、从调度队列摘下、过继孩子、向父发通知。若先释放 PCB 再通知，wait 协议破；若先通知再拆内存，父 wait 到的瞬间子仍占 RAM，也行，但通常先拆用户资源再变僵尸。缺口是这条顺序，不是新的 fork。</p><p><span class="marginnote">内核线程的 stop 没有用户地址空间可拆，但仍要摘队列、释放内核栈。用户进程的 mm 可能被线程共享，最后一条线程才放掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>进入 <code>do_exit</code> 一类路径：不可再回到用户（trapframe 无意义）。释放 <code>mm</code>（若引用到零）、关闭文件、去掉命名空间引用、把状态改为僵尸、<code>exit_notify</code> 唤醒父或过继。真正 <code>free(task)</code> 发生在父 wait 或 init 收割时。错误路径（OOM 杀进程）走同一套，只是退出码不同。</p>',8)),(a(),l(p,null,{default:i(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXIT%5B%22exit%22%5D%20--%3E%20REL%5B%22%E9%87%8A%20mm%20%E4%B8%8E%E6%96%87%E4%BB%B6%22%5D%0A%20%20REL%20--%3E%20CH%5B%22%E8%BF%87%E7%BB%A7%E5%AD%A9%E5%AD%90%22%5D%0A%20%20CH%20--%3E%20Z%5B%22%E5%83%B5%E5%B0%B8%E5%B9%B6%E9%80%9A%E7%9F%A5%E7%88%B6%22%5D%0A%20%20Z%20--%3E%20WAIT%5B%22wait%20%E5%90%8E%E9%87%8A%E6%94%BE%20PCB%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>不能在硬中断里 exit；退出是线程上下文，可睡（关文件可能等磁盘）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>回收把<a href="/cs/process-image">进程映像</a>从厚变薄：用户页先走，PCB 后走。文件表引用计数下降可能触发最后一次写回，那是文件课。与<a href="/cs/syscall-path">系统调用路径</a>的关系：exit 本身也是系统调用，但不返回；汇编从内核直接切到别的线程。</p><p>异常杀掉（非法访问）也汇入同一路径，只是入口是故障而不是自愿 <code>_exit</code>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 cgroup 的收费与 oom_score 写完，不讨论 <code>exit_group</code> 与单线程 <code>exit</code> 的全部差别——点到「进程退出拆线程组」即可。也不把核心转储的文件格式当正文。</p><p>后课默认：用户资源在僵尸之前释放，PCB 在 wait 之后释放。作业控制还要把若干 PCB 编成组，下一课讲进程组与会话。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>exit 先拆用户资源，再成僵尸并通知父；PCB 等 wait。</li><li>杀进程与自愿退出汇入同一回收。</li><li>把进程编成作业是下一课。</li><li>出处：Love, <em>LKD</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',9))])}const P=r(m,[["render",h]]);export{A as __pageData,P as default};
